package glitch

import data.glitch_lib

# Helper to check if a value indicates false/disabled/off for integrity checks
is_disabled_integrity_check(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    regex.match("(?i)(false|disabled|off|no|0)", value.value)
} else {
    value.ir_type == "Integer"
    value.value == 0
}

# Helper to check if a protocol is unreliable without integrity
is_unreliable_protocol(value) {
    value.ir_type == "String"
    regex.match("(?i)^(udp|http)$", value.value)
}

# Helper to check if integrity attributes are missing or disabled
has_missing_integrity_attrs(attrs) {
    # Check for explicitly disabled integrity flags
    some attr in attrs
    integrity_attr_names := ["enable_md5_check", "verify_checksum", "data_integrity_validation", "transfer_validation", "integrity_check", "signature_verification", "enforce_checksum", "validate_log_integrity", "signature_required", "source_verification", "payload_validation", "verify_signature", "checksum_header", "require_signature", "enforce_mac", "message_validation"]
    attr.name in integrity_attr_names
    is_disabled_integrity_check(attr.value)
} else {
    # Check for protocol without integrity
    some attr in attrs
    attr.name in ["protocol", "transport", "proto"]
    is_unreliable_protocol(attr.value)
} else {
    # Check for missing key references when signature required
    some attr in attrs
    attr.name in ["require_signature", "enforce_mac"]
    attr.value.ir_type == "Boolean"
    attr.value.value == true
    not has_signing_keys(attrs)
} else {
    # Check for policies allowing unsigned data
    some attr in attrs
    attr.name in ["allow_unsigned_data", "bypass_integrity_check"]
    attr.value.ir_type == "Boolean"
    attr.value.value == true
}

# Helper to check for signing keys
has_signing_keys(attrs) {
    some attr in attrs
    attr.name in ["signing_key", "mac_key", "signature_key", "hmac_key"]
} else {
    some attr in attrs
    attr.name == "key_type"
    attr.value.ir_type == "String"
    regex.match("(?i)sign|mac|hmac", attr.value.value)
}

# Main detection for CWE-353
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)

    has_missing_integrity_attrs(attrs)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing support for integrity check - Data transmission or storage lacks built-in integrity validation mechanisms (checksums, hashes, or digital signatures)"
    }
}

# Additional detection for missing digital signatures/MACs in cryptographic contexts
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)

    # Find crypto-related resources
    node.type_lower := lower(node.type)
    crypto_related := node.type_lower in ["signing_key", "mac_key", "hmac_key", "crypto_key", "signature"]

    # Check if signature requirement is missing or disabled
    some attr in attrs
    attr.name in ["require_signature", "enforce_mac", "signature_required"]
    is_disabled_integrity_check(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing digital signature or MAC - Cryptographic verification is disabled or not enforced for sensitive operations"
    }
}

